                "number": 1,
                "section": "المقدمة",
                "text": "قَالَ سُلَيْمَانُ هُوَ الْعُيُونِي: سُبْحَانَ رَبِّي الْوَاحِدِ الْمُعِينِ\nمُصَلِّيًا مُسَلِّمًا -يَا مُهْتَدِي- عَلَى الرَّسُولِ الْمُصْطَفَى مُحَمَّدِ\nوَهَذِهِ أَرْجُوزَةٌ خَفِيفَةْ فِي نَحْوِنَا مُفِيدَةٌ لَطِيفَةْ"
